int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;

    if (!p || !facilities) {
        return -1;
    }

    while (bytes_processed < len) {
        unsigned char byte = p[bytes_processed];

        if (byte == 0x00) {
            break;
        }

        unsigned char first_two_bits = (byte >> 6) & 0x03;

        switch (first_two_bits) {
            case 0x00: /* Handle case for 00xx xxxx */
                /* Example logic for a specific facility type */
                if (bytes_processed + 1 >= len) {
                    return -1; /* Not enough data for this facility type */
                }
                facilities->source_address = p[bytes_processed + 1];
                bytes_processed += 2;
                break;

            case 0x01: /* Handle case for 01xx xxxx */
                /* Example logic for another facility type */
                if (bytes_processed + 2 >= len) {
                    return -1; /* Not enough data for this facility type */
                }
                facilities->destination_address = p[bytes_processed + 1];
                facilities->call_sign = p[bytes_processed + 2];
                bytes_processed += 3;
                break;

            case 0x02: /* Handle case for 10xx xxxx */
                /* Additional facility type handling */
                if (bytes_processed + 3 >= len) {
                    return -1; /* Not enough data for this facility type */
                }
                facilities->additional_info = p[bytes_processed + 1];
                bytes_processed += 4;
                break;

            case 0x03: /* Handle case for 11xx xxxx */
                /* Additional facility type handling */
                if (bytes_processed + 4 >= len) {
                    return -1; /* Not enough data for this facility type */
                }
                facilities->more_info = p[bytes_processed + 1];
                bytes_processed += 5;
                break;

            default:
                /* Invalid first two bits, treat as error */
                return -1;
        }
    }

    return bytes_processed;
}
